import type { PermissionState } from '@capacitor/core';

export interface PermissionStatus {
  calendar: PermissionState;
}

export interface CalendarEventOptions {
  id?: string;
  title?: string;
  location?: string;
  notes?: string;
  startDate?: number;
  endDate?: number;
  calendarId?: string;
  allDay?: boolean;
}

/**
 * Options for creating an event. The event ID is generated by the native
 * calendar and returned by `createEvent`, so it is not accepted here.
 */
export type CreateEventOptions = Omit<CalendarEventOptions, 'id'> & { id?: never };

/**
 * Options for updating an event. The event ID identifies the event to update.
 */
export type UpdateEventOptions = Omit<CalendarEventOptions, 'id'> & { id: string };

export interface CreateEventResult {
  id: string;
}

export interface DeleteEventOptions {
  [key: string]: string;
}

export interface CapacitorCalendarPlugin {
  openCalendar(options?: { date: number }): Promise<any>;
  createEvent(options: CreateEventOptions): Promise<CreateEventResult>;
  findEvent(options: CalendarEventOptions): Promise<any>;
  deleteEvent(options: DeleteEventOptions): Promise<any>;
  deleteEventById(options: { id: string }): Promise<any>;
  updateEvent(options: UpdateEventOptions): Promise<any>;
  getAvailableCalendars(): Promise<any>;
  checkPermissions(): Promise<PermissionStatus>;
  requestPermissions(): Promise<PermissionStatus>;
}
